<script setup>
import { ref,computed,watch } from 'vue';
import {foodTitle,foodState} from '../lib/foodPresentation.js';
import { FOOD_BY_ID } from '../data/catalogue.js';
import { portion,MACROS,NUTRIENTS,MEALS,formatNutrient,todayDate } from '../lib/foodNutrition.js';
import { useFoodPhoto } from '../composables/useFoodPhoto.js';
import FoodNutritionEstimate from './FoodNutritionEstimate.vue';
import PortionPicker from './PortionPicker.vue';
import FoodImage from './FoodImage.vue';
import ModalShell from './ModalShell.vue';
import AppIcon from './AppIcon.vue';
const props=defineProps({foodId:String});defineEmits(['close','add']);
const food=computed(()=>FOOD_BY_ID[props.foodId]);const grams=ref(100),date=ref(todayDate()),meal=ref('unspecified');
const aiEstimate=ref(null);watch(()=>props.foodId,()=>aiEstimate.value=null);
const needsEstimate=computed(()=>MACROS.some(m=>typeof food.value?.nutrients?.[m.id]!=='number'));
function estimatedValue(id){const r=aiEstimate.value?.estimate?.values?.[id];return r?`${Math.round(r.low*Number(grams.value)/10)/10}–${Math.round(r.high*Number(grams.value)/10)/10}`:'暂无数据';}
const values=computed(()=>portion(food.value,Number(grams.value)||0));const valid=computed(()=>Number(grams.value)>0&&Number(grams.value)<=5000&&date.value&&date.value<=todayDate());
const {photo,loading:photoLoading,failed:photoFailed,retry:retryPhoto}=useFoodPhoto(()=>food.value);
const credit=computed(()=>photo.value?.imageCredit||photo.value);
const photoNote=computed(()=>photo.value?.imageNote||(photoLoading.value?'正在加载照片。':'此营养样本暂无单独照片。'));
</script>
<template><ModalShell v-if="food" title="食物详情" wide @close="$emit('close')"><div class="vb-food-detail-top"><figure><FoodImage :food="food" :photo="photo" :loading="photoLoading" :failed="photoFailed" :label="false" :lazy="false" class="vb-food-detail-image" /><figcaption>{{ photoNote }}</figcaption></figure><div><p class="vb-eyebrow">{{ food.categoryName }} / {{ food.subcategory }}</p><h1>{{ foodTitle(food) }}</h1><p class="vb-food-state">{{ foodState(food) }}</p><p class="vb-data-note">每 100 克可食部 · 请核对品种和生熟状态。所填重量已经是可食部，不再乘食部比例。</p><p v-if="!food.source" class="vb-inline-warning">{{ food.photoCatalogue?'这道食物暂无标准配方数据，有已保存的AI估算时直接展示；未生成的指标保持未知，不作为数据库值。':'此食物尚无对应的精确成分数据。可以记录重量，营养指标保持未知。' }}</p></div></div><FoodNutritionEstimate v-if="needsEstimate" :food="food" @resolved="aiEstimate=$event" /><form class="vb-food-portion-form" @submit.prevent="valid&&$emit('add',{foodId:food.key,grams:Number(grams),date,meal})"><PortionPicker :food="food" @choose="grams=$event" /><div class="vb-portion-controls"><label>食用可食部重量<input v-model="grams" type="number" min="0.1" max="5000" step="0.1" inputmode="decimal" aria-label="实际食用克数" /><small>克</small></label><label>记录日期<input v-model="date" type="date" :max="todayDate()" required /></label><label>餐次<select v-model="meal"><option v-for="[key,label] in MEALS" :key="key" :value="key">{{ label }}</option></select></label></div><div class="vb-portion-macros"><div v-for="metric in MACROS" :key="metric.id"><span>{{ metric.id==='carbs'?'碳水':metric.name }}</span><strong>{{ values[metric.id]!=null?formatNutrient(values[metric.id]):estimatedValue(metric.id) }} <small v-if="values[metric.id]!=null||aiEstimate?.estimate?.values?.[metric.id]">{{ metric.unit }}{{ values[metric.id]==null?' · AI估算':'' }}</small></strong></div></div><button class="vb-button vb-button-primary" type="submit" :disabled="!valid"><AppIcon name="plus" :size="16" />添加到饮食记录</button><small class="vb-data-note">加入“本次选择”，在饮食记录页保存当天记录。</small></form><details class="vb-food-all-nutrients" :open="!!food.source"><summary>完整营养数据</summary><p class="vb-data-note">碳水为 USDA 差减法，包含膳食纤维；维 A 为 RAE、叶酸为 DFE。不同数据口径不直接等同。</p><div class="vb-nutrient-table"><div class="vb-nutrient-table-head"><span>营养指标</span><span>每 100 克</span><span>本份 {{ grams||0 }} 克</span></div><div v-for="metric in NUTRIENTS" :key="metric.id"><span>{{ metric.name }}</span><span>{{ formatNutrient(food.nutrients[metric.id]) }} <small v-if="food.nutrients[metric.id]!=null">{{ metric.unit }}</small></span><span>{{ formatNutrient(values[metric.id]) }} <small v-if="values[metric.id]!=null">{{ metric.unit }}</small></span></div></div></details><div class="vb-food-sources"><p>完整样本名称：{{ food.name }}</p><h3>数据与图片来源</h3><p v-if="food.source"><a :href="food.source.url" target="_blank" rel="noopener">{{ food.source.name }}</a> · NDB {{ food.source.id }} · {{ food.source.license }}<br />原始条目：{{ food.source.description }}</p><p v-else-if="food.identitySource">食物名称与照片关联：<a :href="food.identitySource.url" target="_blank" rel="noopener">{{ food.identitySource.name }} · {{ food.identitySource.title||food.name }}</a>。名称资料不提供该菜式的营养数值。</p><p v-else>原有食物目录，仅保留名称、类别和用户录入重量。</p><p v-if="credit">图片：<a :href="credit.sourceUrl" target="_blank" rel="noopener">{{ credit.title }}</a> / {{ credit.author }} <a v-if="credit.attributionUrl" :href="credit.attributionUrl" target="_blank" rel="noopener">作者指定署名链接</a> · <a :href="credit.licenseUrl" target="_blank" rel="noopener">{{ credit.license }}</a> · {{ credit.modifications }}</p></div></ModalShell></template>


